import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Versions and compatibility","description":"","frontmatter":{"pageId":"compatibility","contentRevision":2},"headers":[],"relativePath":"en/compatibility.md","filePath":"en/compatibility.md"}'),n={name:"en/compatibility.md"};function r(s,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="versions-and-compatibility" tabindex="-1">Versions and compatibility <a class="header-anchor" href="#versions-and-compatibility" aria-label="Permalink to &quot;Versions and compatibility&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Use RimWorld 1.7, Rimlink 0.8.1 and Harmony 3.x. Server and mod versions must be compatible; the current network protocol is 1. Use a release package and the administrator&#39;s modpack.</p><p>Load order, package IDs, versions, file contents and mod settings may be checked at connection time. The difference dialog explains what to change. Back up local data and close the game before updating.</p><h2 id="checklist" tabindex="-1">How do I check a setup before joining? <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;How do I check a setup before joining? {#checklist}&quot;">​</a></h2><p>Check four independent layers: RimWorld 1.7; Rimlink 0.8.1 on client and server; Harmony 3.x; and the chosen server&#39;s collection. Matching mod names is insufficient: package IDs, versions, order, file contents and shared settings can differ.</p><ol><li>Obtain the Rimlink version and required DLC from the administrator.</li><li>Avoid two active copies of one packageId: a Workshop copy and local folder must not compete.</li><li>Restart after changing the collection. Loaded DLLs cannot be reliably swapped in place.</li><li>Pass the mismatch dialog. Visits/live must also load the host map&#39;s dependencies.</li></ol><p>“Newer” is not automatically compatible with an older server. If Workshop has advanced, use an administrator-approved package or coordinate a server update; never edit the expected hash.</p><h2 id="verified" tabindex="-1">What is verified and what is not promised? <a class="header-anchor" href="#verified" aria-label="Permalink to &quot;What is verified and what is not promised? {#verified}&quot;">​</a></h2><p>Automated server tests do not establish compatibility with every game mod. Mods affecting serialization, pawns, map simulation or UI require collection-specific checks. Before a coordinated upgrade, test login, colony loading, an item transfer and the intended live scenario on a test server.</p><p>Non-Steam package delivery was checked with an isolated copy of a Steam installation. That is not acceptance of an actual GOG runtime. GOG requires enabled password authentication and legally redistributable dependencies; Core/DLC are never delivered.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Steam authentication requires Steam to be running. GOG needs password login enabled and a redistributable server package; an actual GOG runtime has not yet been verified. Rimlink does not redistribute Core or DLC.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./players/install">Installing the mod</a></li><li><a href="./players/modpacks">Server modpacks</a></li><li><a href="./admins/updating">Updating server and clients</a></li></ul>',16)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
